#include <Arduino.h>

float angle = 0;
float alpha = 0.96; // Filter coefficient

void updateOrientation(float gyroRate, float accelAngle, float dt) {
  angle = alpha * (angle + gyroRate * dt) + (1.0 - alpha) * accelAngle;
}

CREATE TABLE attendance (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  institution_id UUID NOT NULL REFERENCES institutions(id),
  student_id UUID NOT NULL REFERENCES students(id),
  lab_session_id UUID NOT NULL REFERENCES lab_sessions(id),
  present BOOLEAN DEFAULT FALSE
);

ALTER TABLE attendance ENABLE ROW LEVEL SECURITY;

CREATE POLICY tenant_isolation ON attendance
  USING (institution_id = current_setting('app.institution_id')::UUID);
